create table if not exists users(id serial primary key,name text not null,email text unique not null,password text not null,role text not null default 'user' check(role in('user','treasurer','admin')),member_code text unique,member_until timestamptz,created_at timestamptz default now());
create table if not exists events(id serial primary key,title text not null,description text,venue text,starts_at timestamptz not null,capacity int not null,price int not null,member_price int not null,status text default 'published');
create table if not exists tickets(id serial primary key,event_id int references events on delete cascade,user_id int references users on delete cascade,code text unique not null,price int not null,checked_in boolean default false,checked_at timestamptz,created_at timestamptz default now());
create table if not exists announcements(id serial primary key,title text not null,body text not null,category text default 'general',pinned boolean default false,author_id int references users on delete set null,created_at timestamptz default now());
create table if not exists products(id serial primary key,name text not null,description text,price int not null,image text,sizes jsonb not null default '{}');
create table if not exists orders(id serial primary key,user_id int references users on delete cascade,product_id int references products on delete set null,product_name text,size text,qty int,total int,discount int default 0,status text default 'paid',created_at timestamptz default now());
create table if not exists memberships(id serial primary key,user_id int references users on delete cascade,amount int,valid_until timestamptz,created_at timestamptz default now());
create table if not exists fundraisers(id serial primary key,title text not null,goal int default 0,event_date date);
create table if not exists tasks(id serial primary key,fundraiser_id int references fundraisers on delete cascade,title text not null,assignee_id int references users on delete set null,status text default 'todo',due date);
create table if not exists expenses(id serial primary key,user_id int references users on delete cascade,amount int not null,description text,receipt_url text,event_id int references events on delete set null,status text default 'pending',created_at timestamptz default now());
create table if not exists ledger(id serial primary key,type text check(type in('income','expense')),source text,amount int not null,description text,event_id int references events on delete set null,created_at timestamptz default now());
